import java.util.Scanner;

public class Main {

    private static class PowerInfo {
        int cur;
        double value;

        PowerInfo(int cur, double value) {
            this.cur = cur;
            this.value = value;
        }
    }

    public void solve() {
        Scanner sc = new Scanner(System.in);
        long W = sc.nextLong();
        long M = sc.nextLong();

        PowerInfo info = ceilPower(W, M);
        double pw = info.value;

        if (pw == M) {
            System.out.println("YES");
            return;
        }

        long max = (long) pw;
        long sum = (max - 1) / (W - 1);
        if (max - sum == M) {
            System.out.println("YES");
            return;
        }

        System.out.println(dfs(W, M) ? "YES" : "NO");
    }

    private PowerInfo ceilPower(long W, long M) {
        int cur = 0;
        while (Math.pow(W, cur) < M) {
            cur++;
        }
        return new PowerInfo(cur, Math.pow(W, cur));
    }

    private boolean dfs(long W, long M) {
        if (M == 1) {
            return true;
        }
        if (M % W == 0) {
            return dfs(W, M / W);
        } else if ((M - 1) % W == 0) {
            return dfs(W, (M - 1) / W);
        } else if ((M + 1) % W == 0) {
            return dfs(W, (M + 1) / W);
        }
        return false;
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}
